// The KIE board doubles the y in ScaryyJod; Liquipedia records the player as ScaryJod.
playerAliases.scaryyjod = playerAliases.scaryjod

const normalizePlayerName = (value: string) => value.toLowerCase().replace(/[^a-z0-9]/g, '')
const detailedPlayers = detailedPlayerProfiles.map((profile) => {
  const ranking = kiePlayerRankings.find((row) => [profile.name, ...profile.aliases].some((name) => normalizePlayerName(name) === normalizePlayerName(row.name)))
  return ranking ? { ...profile, kieRanking: { rank: ranking.rank, points: ranking.points, eliminations: ranking.eliminations, change: ranking.change } } : profile
})
const knownPlayers = new Set(detailedPlayers.flatMap((profile) => [profile.name, ...profile.aliases].map(normalizePlayerName)))
const rankedPlayerProfiles: PlayerProfileRecord[] = kiePlayerRankings.flatMap((ranking) => {
  const key = normalizePlayerName(ranking.name)
  const extra = playerAliases[key]
  const displayName = extra?.name ?? ranking.name
  const aliases = extra?.aliases ?? []
  if ([displayName, ranking.name, ...aliases].some((name) => knownPlayers.has(normalizePlayerName(name)))) return []
  knownPlayers.add(key)
  return [{
    id: displayName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''), name: displayName,
    aliases, nationality: 'India', role: extra?.role ?? 'BGMI player', currentTeam: ranking.team, born: extra?.born,
    stats: extra?.stats, achievements: extra?.achievements ?? [], results: extra?.results, awards: extra?.awards, history: extra?.history,
    kieRanking: { rank: ranking.rank, points: ranking.points, eliminations: ranking.eliminations, change: ranking.change },
    liquipediaUrl: extra?.liquipedia,
    esportStatsUrl: `https://esportstats.in/players/${encodeURIComponent(ranking.name.toUpperCase())}`,
  }]
})
