export const playerProfiles: PlayerProfileRecord[] = [...detailedPlayers, ...rankedPlayerProfiles].map((profile) => {
  const hitboardKey = normalizePlayerName(profile.name)
  const hitboardSplit = officialHitboardSplits[hitboardKey]
  const eventStats = publishedEventStats[hitboardKey]
  if (!hitboardSplit && !eventStats) return profile
  return {
    ...profile,
    hitboardSplit,
    eventStats,
    esportStatsUrl: profile.esportStatsUrl ?? `https://esportstats.in/players/${encodeURIComponent(profile.name.toUpperCase())}`,
  }
})
